package com.instagramhibernate.dao; // Declares DAO package.
import java.util.List; // Imports List result type.
import org.hibernate.Session; // Imports Hibernate Session.
import org.hibernate.query.Query; // Imports Hibernate Query.
import com.instagramhibernate.entity.*; // Imports mapped entities used in HQL examples.
import com.instagramhibernate.util.HibernateUtil; // Imports SessionFactory utility.
/** Demonstration query catalog based on the attached document; every method opens and closes its own Session. */
public class HqlQueryCatalogDAO { // Groups the document's common HQL patterns for training.
    public List<User> allUsers() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("from User", User.class); return q.getResultList(); } finally { s.close(); } } // HQL 1: all users.
    public User userById(Long id) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("from User u where u.id = :id", User.class); q.setParameter("id", id); return q.uniqueResult(); } finally { s.close(); } } // HQL 2: user by id.
    public User userByUsername(String name) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("from User u where u.username = :username", User.class); q.setParameter("username", name); return q.uniqueResult(); } finally { s.close(); } } // HQL 3: username lookup.
    public List<User> searchUsers(String keyword) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("from User u where lower(u.username) like lower(:k)", User.class); q.setParameter("k", "%" + keyword + "%"); return q.getResultList(); } finally { s.close(); } } // HQL 4: LIKE search.
    public int updateUserBio(Long id, String bio) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("update User u set u.bio = :bio where u.id = :id"); q.setParameter("bio", bio); q.setParameter("id", id); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // HQL 5: bulk update.
    public int deleteUser(Long id) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("delete from User u where u.id = :id"); q.setParameter("id", id); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // HQL 6: bulk delete.
    public List<Post> allPosts() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("from Post p order by p.createdAt desc", Post.class); return q.getResultList(); } finally { s.close(); } } // HQL 7: posts newest first.
    public List<Post> postsByUser(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("from Post p where p.user.id = :id", Post.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // HQL 8: posts by user.
    public List<Post> feed(Long userId, int page, int size) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select p from Post p join fetch p.user where p.user.id = :id or p.user.id in (select f.following.id from Follower f where f.follower.id = :id) order by p.createdAt desc", Post.class); q.setParameter("id", userId); q.setFirstResult(Math.max(0, page) * size); q.setMaxResults(size); return q.getResultList(); } finally { s.close(); } } // HQL 9: feed plus pagination and JOIN FETCH.
    public List<Post> searchCaptions(String text) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("from Post p where lower(p.caption) like lower(:text)", Post.class); q.setParameter("text", "%" + text + "%"); return q.getResultList(); } finally { s.close(); } } // HQL 10: caption search.
    public List<Comment> comments(Long postId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Comment> q = s.createQuery("from Comment c where c.post.id = :id order by c.createdAt asc", Comment.class); q.setParameter("id", postId); return q.getResultList(); } finally { s.close(); } } // HQL 11: comments.
    public int deleteComment(Long id) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("delete from Comment c where c.id = :id"); q.setParameter("id", id); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // HQL 12: delete comment.
    public int unlike(Long postId, Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("delete from Like l where l.post.id = :p and l.user.id = :u"); q.setParameter("p", postId); q.setParameter("u", userId); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // HQL 13: unlike.
    public long likeCount(Long postId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(l) from Like l where l.post.id = :id", Long.class); q.setParameter("id", postId); return q.uniqueResult().longValue(); } finally { s.close(); } } // HQL 14: count likes.
    public List<User> usersWhoLiked(Long postId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("select l.user from Like l where l.post.id = :id", User.class); q.setParameter("id", postId); return q.getResultList(); } finally { s.close(); } } // HQL 15: users who liked a post.
    public int unfollow(Long followerId, Long followingId) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("delete from Follower f where f.follower.id = :a and f.following.id = :b"); q.setParameter("a", followerId); q.setParameter("b", followingId); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // HQL 16: unfollow.
    public List<User> followers(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("select f.follower from Follower f where f.following.id = :id", User.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // HQL 17: followers.
    public List<User> following(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("select f.following from Follower f where f.follower.id = :id", User.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // HQL 18: following.
    public long followerCount(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(f) from Follower f where f.following.id = :id", Long.class); q.setParameter("id", userId); return q.uniqueResult().longValue(); } finally { s.close(); } } // HQL 19: count followers.
    public List<Story> activeStories() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Story> q = s.createQuery("from Story st where st.expiresAt > current_timestamp order by st.createdAt desc", Story.class); return q.getResultList(); } finally { s.close(); } } // HQL 20: active stories.
    public List<User> storyViewers(Long storyId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("select sv.user from StoryView sv where sv.story.id = :id", User.class); q.setParameter("id", storyId); return q.getResultList(); } finally { s.close(); } } // HQL 21: story viewers.
    public List<Hashtag> searchHashtags(String name) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Hashtag> q = s.createQuery("from Hashtag h where h.name like :name", Hashtag.class); q.setParameter("name", "%" + name + "%"); return q.getResultList(); } finally { s.close(); } } // HQL 22: hashtag search.
    public List<Post> postsForHashtag(String hashtag) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select ph.post from PostHashtag ph where ph.hashtag.name = :name order by ph.post.createdAt desc", Post.class); q.setParameter("name", hashtag); return q.getResultList(); } finally { s.close(); } } // HQL 23: posts by hashtag.
    public List<Post> savedPosts(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select sp.post from SavedPost sp where sp.user.id = :id order by sp.id desc", Post.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // HQL 24: saved posts.
    public List<Message> conversationMessages(Long conversationId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Message> q = s.createQuery("from Message m where m.conversation.id = :id order by m.sentAt asc", Message.class); q.setParameter("id", conversationId); return q.getResultList(); } finally { s.close(); } } // HQL 25: conversation messages.
    public List<Notification> unreadNotifications(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Notification> q = s.createQuery("from Notification n where n.user.id = :id and n.isRead = false order by n.createdAt desc", Notification.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // HQL 26: unread notifications.
    public int markNotificationRead(Long id) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("update Notification n set n.isRead = true where n.id = :id"); q.setParameter("id", id); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // HQL 27: mark notification read.
    public List<Object[]> mostLikedPosts() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Object[]> q = s.createQuery("select p, count(l) from Post p left join Like l on l.post = p group by p order by count(l) desc", Object[].class); return q.getResultList(); } finally { s.close(); } } // HQL 28: aggregation and GROUP BY.
    public List<Object[]> usersWithMostFollowers() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Object[]> q = s.createQuery("select f.following, count(f) from Follower f group by f.following order by count(f) desc", Object[].class); return q.getResultList(); } finally { s.close(); } } // HQL 29: follower aggregation.
    public List<Post> postsWithMoreThanLikes(long minimum) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select p from Post p join Like l on l.post = p group by p having count(l) > :minimum", Post.class); q.setParameter("minimum", minimum); return q.getResultList(); } finally { s.close(); } } // HQL 30: HAVING.
    public List<Post> pagedPosts(int page, int pageSize) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("from Post p order by p.createdAt desc", Post.class); q.setFirstResult(Math.max(0, page) * pageSize); q.setMaxResults(pageSize); return q.getResultList(); } finally { s.close(); } } // HQL 31: pagination.
    public List<Post> nativePostsByUser(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { org.hibernate.query.NativeQuery<Post> q = s.createNativeQuery("select * from posts where user_id = :userId", Post.class); q.setParameter("userId", userId); return q.getResultList(); } finally { s.close(); } } // SQL 32: native SQL through Hibernate.

    public boolean userLikedPost(Long postId, Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(l) from Like l where l.post.id = :p and l.user.id = :u", Long.class); q.setParameter("p", postId); q.setParameter("u", userId); return q.uniqueResult().longValue() > 0L; } finally { s.close(); } } // Checks whether a user liked a post.
    public long followingCount(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(f) from Follower f where f.follower.id = :id", Long.class); q.setParameter("id", userId); return q.uniqueResult().longValue(); } finally { s.close(); } } // Counts accounts followed by a user.
    public boolean isFollowing(Long followerId, Long followingId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(f) from Follower f where f.follower.id = :a and f.following.id = :b", Long.class); q.setParameter("a", followerId); q.setParameter("b", followingId); return q.uniqueResult().longValue() > 0L; } finally { s.close(); } } // Checks follow relationship.
    public List<User> mutualFollowing(Long firstUserId, Long secondUserId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<User> q = s.createQuery("select f1.following from Follower f1 where f1.follower.id = :first and f1.following.id in (select f2.following.id from Follower f2 where f2.follower.id = :second)", User.class); q.setParameter("first", firstUserId); q.setParameter("second", secondUserId); return q.getResultList(); } finally { s.close(); } } // Finds users followed by both accounts.
    public List<Story> activeStoriesForUser(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Story> q = s.createQuery("from Story st where st.user.id = :id and st.expiresAt > current_timestamp order by st.createdAt desc", Story.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // Finds active stories for one user.
    public long storyViewCount(Long storyId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(v) from StoryView v where v.story.id = :id", Long.class); q.setParameter("id", storyId); return q.uniqueResult().longValue(); } finally { s.close(); } } // Counts views for a story.
    public int unsavePost(Long userId, Long postId) { Session s = HibernateUtil.getSessionFactory().openSession(); org.hibernate.Transaction tx = s.beginTransaction(); try { Query<?> q = s.createQuery("delete from SavedPost sp where sp.user.id = :u and sp.post.id = :p"); q.setParameter("u", userId); q.setParameter("p", postId); int n = q.executeUpdate(); tx.commit(); return n; } catch (RuntimeException e) { tx.rollback(); throw e; } finally { s.close(); } } // Removes a saved post.
    public List<com.instagramhibernate.entity.Conversation> conversationsForUser(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<com.instagramhibernate.entity.Conversation> q = s.createQuery("select cu.conversation from ConversationUser cu where cu.user.id = :id", com.instagramhibernate.entity.Conversation.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // Finds conversations for a user.
    public List<Message> searchMessages(String keyword) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Message> q = s.createQuery("from Message m where lower(m.messageText) like lower(:keyword)", Message.class); q.setParameter("keyword", "%" + keyword + "%"); return q.getResultList(); } finally { s.close(); } } // Searches message text.
    public long unreadNotificationCount(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(n) from Notification n where n.user.id = :id and n.isRead = false", Long.class); q.setParameter("id", userId); return q.uniqueResult().longValue(); } finally { s.close(); } } // Counts unread notifications.
    public long postCountForUser(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(p) from Post p where p.user.id = :id", Long.class); q.setParameter("id", userId); return q.uniqueResult().longValue(); } finally { s.close(); } } // Counts posts by user.
    public long commentCountForPost(Long postId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Long> q = s.createQuery("select count(c) from Comment c where c.post.id = :id", Long.class); q.setParameter("id", postId); return q.uniqueResult().longValue(); } finally { s.close(); } } // Counts comments for a post.
    public List<Post> postsWithMoreThan100Likes() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select p from Post p join Like l on l.post = p group by p having count(l) > 100", Post.class); return q.getResultList(); } finally { s.close(); } } // Finds posts with more than 100 likes.
    public List<Object[]> usersWithMostPosts() { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Object[]> q = s.createQuery("select p.user, count(p) from Post p group by p.user order by count(p) desc", Object[].class); return q.getResultList(); } finally { s.close(); } } // Ranks users by post count.
    public List<Post> postsWithAuthor(Long postId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select p from Post p join fetch p.user where p.id = :id", Post.class); q.setParameter("id", postId); return q.getResultList(); } finally { s.close(); } } // Demonstrates JOIN FETCH for a single post.
    public List<Post> followingFeedOnly(Long userId) { Session s = HibernateUtil.getSessionFactory().openSession(); try { Query<Post> q = s.createQuery("select p from Post p join fetch p.user where p.user.id in (select f.following.id from Follower f where f.follower.id = :id) order by p.createdAt desc", Post.class); q.setParameter("id", userId); return q.getResultList(); } finally { s.close(); } } // Feed limited to followed accounts.
}
